contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller) public payable {
        require(caller != address(this), "caller must not be the test contract");

        c.withdrawAll(); if (__ESBMC_reverted()) return;
        bool ownerReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            ownerReverted = true;
        } else {
            ownerReverted = false;
        }

        assert(!ownerReverted && address(c).balance == 0);
    }

    receive() external payable {}
}

